void de_ep_read_world_delta(mpack_reader_t *r, de_ep_arena *a, de_ep_world_delta *out) {
    memset(out, 0, sizeof(*out));
    (void)a;
    uint64_t seen = 0;
    uint32_t n = mpack_expect_map(r);
    for (uint32_t i = 0; i < n && mpack_reader_error(r) == mpack_ok; ++i) {
        de_ep_str k = de_ep_read_key(r);
        if (de_ep_str_eq(k, "subscription")) {
            seen |= (uint64_t)1 << 0;
            out->subscription = mpack_expect_u32(r);
        } else if (de_ep_str_eq(k, "resync")) {
            seen |= (uint64_t)1 << 1;
            out->has_resync = true;
            out->resync = mpack_expect_bool(r);
        } else if (de_ep_str_eq(k, "spawned")) {
            seen |= (uint64_t)1 << 2;
            out->spawned.count = mpack_expect_array(r);
            out->spawned.items = (de_ep_entity_row *)de_ep_arena_array(r, a, out->spawned.count, sizeof(*out->spawned.items));
            for (uint32_t i_3 = 0; out->spawned.items && i_3 < out->spawned.count; ++i_3)
            {
                de_ep_read_entity_row(r, a, &out->spawned.items[i_3]);
            }
            mpack_done_array(r);
        } else if (de_ep_str_eq(k, "despawned")) {
            seen |= (uint64_t)1 << 3;
            out->despawned.count = mpack_expect_array(r);
            out->despawned.items = (uint64_t *)de_ep_arena_array(r, a, out->despawned.count, sizeof(*out->despawned.items));
            for (uint32_t i_3 = 0; out->despawned.items && i_3 < out->despawned.count; ++i_3)
            {
                out->despawned.items[i_3] = mpack_expect_u64(r);
            }
            mpack_done_array(r);
        } else if (de_ep_str_eq(k, "changed")) {
            seen |= (uint64_t)1 << 4;
            out->changed.count = mpack_expect_array(r);
            out->changed.items = (de_ep_field_change *)de_ep_arena_array(r, a, out->changed.count, sizeof(*out->changed.items));
            for (uint32_t i_3 = 0; out->changed.items && i_3 < out->changed.count; ++i_3)
            {
                de_ep_read_field_change(r, a, &out->changed.items[i_3]);
            }
            mpack_done_array(r);
        } else {
            mpack_discard(r);
        }
    }
    mpack_done_map(r);
    if ((seen & UINT64_C(29)) != UINT64_C(29))
        mpack_reader_flag_error(r, mpack_error_data);
}

